-- F20 Health — Multimodal activities and multiple daily sessions
-- Filename generated by Supabase CLI 3.1.0.
-- Strength training remains in M4/F19. Non-strength modalities use F20.

-- 1) EXTENSIBLE MODALITY CATALOG

CREATE TABLE public.health_activity_modalities (
  code text PRIMARY KEY,
  name text NOT NULL,
  metric_profile text NOT NULL CHECK (
    metric_profile IN (
      'distance','machine','mind_body','dance','sport','mobility','other'
    )
  ),
  sort_order integer NOT NULL DEFAULT 100,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (btrim(code) <> ''),
  CHECK (btrim(name) <> '')
);

INSERT INTO public.health_activity_modalities (
  code,name,metric_profile,sort_order
)
VALUES
  ('running','Corrida','distance',10),
  ('walking','Caminhada','distance',20),
  ('cycling','Ciclismo','distance',30),
  ('swimming','Natação','distance',40),
  ('rowing','Remo','machine',50),
  ('elliptical','Elíptico','machine',60),
  ('stairs','Escada / Stair','machine',70),
  ('cardio_other','Cardio geral','machine',80),
  ('pilates','Pilates','mind_body',90),
  ('yoga','Yoga','mind_body',100),
  ('mobility','Mobilidade','mobility',110),
  ('dance','Dança / Ritmos','dance',120),
  ('hiking','Trilha','distance',130),
  ('sport','Esporte','sport',140),
  ('martial_arts','Artes marciais','sport',150),
  ('other','Outra atividade','other',999)
ON CONFLICT (code) DO UPDATE
SET
  name=EXCLUDED.name,
  metric_profile=EXCLUDED.metric_profile,
  sort_order=EXCLUDED.sort_order,
  is_active=true,
  updated_at=now();

CREATE TRIGGER health_activity_modalities_updated_at
BEFORE UPDATE ON public.health_activity_modalities
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE public.health_activity_modalities ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.health_activity_modalities
FROM PUBLIC, anon, authenticated;

GRANT SELECT ON public.health_activity_modalities
TO authenticated;

CREATE POLICY health_activity_modalities_select
ON public.health_activity_modalities
FOR SELECT
TO authenticated
USING (true);

-- 2) ACTIVITY SESSIONS

CREATE TABLE public.health_activity_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  athlete_id uuid NOT NULL
    REFERENCES public.health_athletes(id) ON DELETE CASCADE,

  modality_code text NOT NULL
    REFERENCES public.health_activity_modalities(code) ON DELETE RESTRICT,

  title text NOT NULL,

  source text NOT NULL DEFAULT 'live' CHECK (
    source IN ('live','manual','import')
  ),

  status text NOT NULL DEFAULT 'active' CHECK (
    status IN ('active','paused','completed','aborted')
  ),

  started_at timestamptz NOT NULL DEFAULT now(),
  ended_at timestamptz NULL,

  paused_at timestamptz NULL,

  pause_accumulated_seconds integer NOT NULL DEFAULT 0 CHECK (
    pause_accumulated_seconds >= 0
  ),

  active_duration_seconds integer NULL CHECK (
    active_duration_seconds IS NULL OR active_duration_seconds >= 0
  ),

  distance_meters numeric(12,2) NULL CHECK (
    distance_meters IS NULL OR distance_meters >= 0
  ),

  calories_kcal numeric(10,2) NULL CHECK (
    calories_kcal IS NULL OR calories_kcal >= 0
  ),

  avg_hr_bpm integer NULL CHECK (
    avg_hr_bpm IS NULL OR avg_hr_bpm BETWEEN 20 AND 260
  ),

  max_hr_bpm integer NULL CHECK (
    max_hr_bpm IS NULL OR max_hr_bpm BETWEEN 20 AND 260
  ),

  rpe numeric(3,1) NULL CHECK (
    rpe IS NULL OR (rpe >= 0 AND rpe <= 10)
  ),

  cadence_spm numeric(8,2) NULL CHECK (
    cadence_spm IS NULL OR cadence_spm >= 0
  ),

  elevation_gain_m numeric(10,2) NULL CHECK (
    elevation_gain_m IS NULL OR elevation_gain_m >= 0
  ),

  steps integer NULL CHECK (
    steps IS NULL OR steps >= 0
  ),

  avg_pace_seconds_per_km numeric(10,2) NULL CHECK (
    avg_pace_seconds_per_km IS NULL OR avg_pace_seconds_per_km >= 0
  ),

  avg_speed_kmh numeric(10,3) NULL CHECK (
    avg_speed_kmh IS NULL OR avg_speed_kmh >= 0
  ),

  notes text NULL,

  client_event_id uuid NOT NULL,

  created_by_auth_user_id uuid NOT NULL
    REFERENCES auth.users(id) ON DELETE RESTRICT DEFAULT auth.uid(),

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  UNIQUE (id, athlete_id),
  UNIQUE (athlete_id, client_event_id),

  CHECK (btrim(title) <> ''),

  CHECK (
    (status IN ('completed','aborted') AND ended_at IS NOT NULL)
    OR
    (status IN ('active','paused') AND ended_at IS NULL)
  ),

  CHECK (
    (status='paused' AND paused_at IS NOT NULL)
    OR
    (status<>'paused')
  ),

  CHECK (
    avg_hr_bpm IS NULL OR max_hr_bpm IS NULL OR max_hr_bpm >= avg_hr_bpm
  )
);

CREATE UNIQUE INDEX health_activity_sessions_one_open_per_athlete
ON public.health_activity_sessions(athlete_id)
WHERE status IN ('active','paused');

CREATE INDEX health_activity_sessions_athlete_time_idx
ON public.health_activity_sessions(athlete_id, started_at DESC);

CREATE INDEX health_activity_sessions_modality_time_idx
ON public.health_activity_sessions(modality_code, started_at DESC);

CREATE TRIGGER health_activity_sessions_updated_at
BEFORE UPDATE ON public.health_activity_sessions
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- 3) OPTIONAL SEGMENTS / LAPS

CREATE TABLE public.health_activity_segments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  activity_session_id uuid NOT NULL,
  athlete_id uuid NOT NULL
    REFERENCES public.health_athletes(id) ON DELETE CASCADE,

  sequence_order integer NOT NULL CHECK (sequence_order >= 1),

  segment_type text NOT NULL DEFAULT 'lap' CHECK (
    segment_type IN (
      'lap','warmup','work','recovery','cooldown','interval','other'
    )
  ),

  label text NULL,

  duration_seconds integer NULL CHECK (
    duration_seconds IS NULL OR duration_seconds >= 0
  ),

  distance_meters numeric(12,2) NULL CHECK (
    distance_meters IS NULL OR distance_meters >= 0
  ),

  pace_seconds_per_km numeric(10,2) NULL CHECK (
    pace_seconds_per_km IS NULL OR pace_seconds_per_km >= 0
  ),

  avg_hr_bpm integer NULL CHECK (
    avg_hr_bpm IS NULL OR avg_hr_bpm BETWEEN 20 AND 260
  ),

  cadence_spm numeric(8,2) NULL CHECK (
    cadence_spm IS NULL OR cadence_spm >= 0
  ),

  notes text NULL,

  client_event_id uuid NOT NULL,

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  UNIQUE (athlete_id, client_event_id),
  UNIQUE (activity_session_id, sequence_order),

  CONSTRAINT health_activity_segments_session_athlete_fkey
    FOREIGN KEY (activity_session_id, athlete_id)
    REFERENCES public.health_activity_sessions(id, athlete_id)
    ON DELETE CASCADE
);

CREATE INDEX health_activity_segments_session_idx
ON public.health_activity_segments(activity_session_id, sequence_order);

CREATE TRIGGER health_activity_segments_updated_at
BEFORE UPDATE ON public.health_activity_segments
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- 4) AUDIT EVENTS

CREATE TABLE public.health_activity_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  athlete_id uuid NOT NULL
    REFERENCES public.health_athletes(id) ON DELETE CASCADE,

  activity_session_id uuid NOT NULL,

  activity_segment_id uuid NULL
    REFERENCES public.health_activity_segments(id) ON DELETE SET NULL,

  event_type text NOT NULL CHECK (
    event_type IN (
      'activity_started','activity_paused','activity_resumed',
      'activity_completed','activity_aborted',
      'activity_updated','segment_added','note'
    )
  ),

  source text NOT NULL DEFAULT 'user' CHECK (
    source IN ('user','system','sync','import')
  ),

  client_event_id uuid NOT NULL,

  occurred_at timestamptz NOT NULL DEFAULT now(),
  recorded_at timestamptz NOT NULL DEFAULT now(),

  payload jsonb NULL,

  created_by_auth_user_id uuid NULL
    REFERENCES auth.users(id) ON DELETE SET NULL DEFAULT auth.uid(),

  UNIQUE (athlete_id, client_event_id),

  CONSTRAINT health_activity_events_session_athlete_fkey
    FOREIGN KEY (activity_session_id, athlete_id)
    REFERENCES public.health_activity_sessions(id, athlete_id)
    ON DELETE CASCADE
);

CREATE INDEX health_activity_events_session_idx
ON public.health_activity_events(activity_session_id, occurred_at, recorded_at);

