-- 6) CROSS-DOMAIN LIVE SESSION GUARD

CREATE OR REPLACE FUNCTION public.health_f20_guard_single_live_session()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.status NOT IN ('active','paused') THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME='health_activity_sessions' THEN
    IF EXISTS (
      SELECT 1
      FROM public.health_workout_sessions ws
      WHERE ws.athlete_id=NEW.athlete_id
        AND ws.status IN ('active','paused')
    ) THEN
      RAISE EXCEPTION 'finish or pause-and-close the open strength workout before starting another live activity';
    END IF;
  ELSIF TG_TABLE_NAME='health_workout_sessions' THEN
    IF EXISTS (
      SELECT 1
      FROM public.health_activity_sessions a
      WHERE a.athlete_id=NEW.athlete_id
        AND a.status IN ('active','paused')
    ) THEN
      RAISE EXCEPTION 'finish the open activity before starting a strength workout';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER health_f20_guard_activity_live_session
BEFORE INSERT OR UPDATE OF status
ON public.health_activity_sessions
FOR EACH ROW
EXECUTE FUNCTION public.health_f20_guard_single_live_session();

CREATE TRIGGER health_f20_guard_workout_live_session
BEFORE INSERT OR UPDATE OF status
ON public.health_workout_sessions
FOR EACH ROW
EXECUTE FUNCTION public.health_f20_guard_single_live_session();

-- 7) START LIVE ACTIVITY

CREATE OR REPLACE FUNCTION public.health_f20_start_activity(
  p_athlete_id uuid,
  p_modality_code text,
  p_title text,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_id uuid;
  v_title text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  IF NOT public.health_can_write_athlete(p_athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  SELECT s.id
  INTO v_id
  FROM public.health_activity_sessions s
  WHERE s.athlete_id=p_athlete_id
    AND s.client_event_id=p_client_event_id
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT COALESCE(NULLIF(btrim(p_title),''),m.name)
  INTO v_title
  FROM public.health_activity_modalities m
  WHERE m.code=p_modality_code
    AND m.is_active=true;

  IF v_title IS NULL THEN
    RAISE EXCEPTION 'activity modality not found or inactive';
  END IF;

  INSERT INTO public.health_activity_sessions (
    athlete_id,
    modality_code,
    title,
    source,
    status,
    started_at,
    client_event_id,
    created_by_auth_user_id
  )
  VALUES (
    p_athlete_id,
    p_modality_code,
    v_title,
    'live',
    'active',
    clock_timestamp(),
    p_client_event_id,
    auth.uid()
  )
  RETURNING id INTO v_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    p_athlete_id,
    v_id,
    'activity_started',
    'user',
    gen_random_uuid(),
    jsonb_build_object(
      'modality_code',p_modality_code,
      'title',v_title
    ),
    auth.uid()
  );

  RETURN v_id;
END;
$$;

-- 8) PAUSE / RESUME

CREATE OR REPLACE FUNCTION public.health_f20_pause_activity(
  p_activity_id uuid,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_activity public.health_activity_sessions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_activity
  FROM public.health_activity_sessions
  WHERE id=p_activity_id
  FOR UPDATE;

  IF v_activity.id IS NULL THEN
    RAISE EXCEPTION 'activity not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_activity.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_activity_events e
    WHERE e.athlete_id=v_activity.athlete_id
      AND e.client_event_id=p_client_event_id
  ) THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status='paused' THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status<>'active' THEN
    RAISE EXCEPTION 'activity is not active';
  END IF;

  UPDATE public.health_activity_sessions
  SET
    status='paused',
    paused_at=v_now
  WHERE id=p_activity_id
    AND athlete_id=v_activity.athlete_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_activity.athlete_id,
    p_activity_id,
    'activity_paused',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object('paused_at',v_now),
    auth.uid()
  );

  RETURN p_activity_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.health_f20_resume_activity(
  p_activity_id uuid,
  p_client_event_id uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_activity public.health_activity_sessions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_pause_seconds integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_activity
  FROM public.health_activity_sessions
  WHERE id=p_activity_id
  FOR UPDATE;

  IF v_activity.id IS NULL THEN
    RAISE EXCEPTION 'activity not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_activity.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_activity_events e
    WHERE e.athlete_id=v_activity.athlete_id
      AND e.client_event_id=p_client_event_id
  ) THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status='active' THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status<>'paused' OR v_activity.paused_at IS NULL THEN
    RAISE EXCEPTION 'activity is not paused';
  END IF;

  v_pause_seconds := GREATEST(
    0,
    floor(extract(epoch from (v_now-v_activity.paused_at)))::integer
  );

  UPDATE public.health_activity_sessions
  SET
    status='active',
    pause_accumulated_seconds=pause_accumulated_seconds+v_pause_seconds,
    paused_at=NULL
  WHERE id=p_activity_id
    AND athlete_id=v_activity.athlete_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_activity.athlete_id,
    p_activity_id,
    'activity_resumed',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object('pause_seconds',v_pause_seconds),
    auth.uid()
  );

  RETURN p_activity_id;
END;
$$;

-- 9) COMPLETE LIVE ACTIVITY

CREATE OR REPLACE FUNCTION public.health_f20_complete_activity(
  p_activity_id uuid,
  p_client_event_id uuid,
  p_distance_meters numeric DEFAULT NULL,
  p_calories_kcal numeric DEFAULT NULL,
  p_avg_hr_bpm integer DEFAULT NULL,
  p_max_hr_bpm integer DEFAULT NULL,
  p_rpe numeric DEFAULT NULL,
  p_cadence_spm numeric DEFAULT NULL,
  p_elevation_gain_m numeric DEFAULT NULL,
  p_steps integer DEFAULT NULL,
  p_notes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_activity public.health_activity_sessions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_current_pause integer := 0;
  v_duration integer;
  v_pace numeric := NULL;
  v_speed numeric := NULL;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_activity
  FROM public.health_activity_sessions
  WHERE id=p_activity_id
  FOR UPDATE;

  IF v_activity.id IS NULL THEN
    RAISE EXCEPTION 'activity not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_activity.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_activity_events e
    WHERE e.athlete_id=v_activity.athlete_id
      AND e.client_event_id=p_client_event_id
  ) THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status='completed' THEN
    RETURN p_activity_id;
  END IF;

  IF v_activity.status NOT IN ('active','paused') THEN
    RAISE EXCEPTION 'activity is not open';
  END IF;

  IF v_activity.status='paused' AND v_activity.paused_at IS NOT NULL THEN
    v_current_pause := GREATEST(
      0,
      floor(extract(epoch from (v_now-v_activity.paused_at)))::integer
    );
  END IF;

  v_duration := GREATEST(
    0,
    floor(
      extract(epoch from (v_now-v_activity.started_at))
      - v_activity.pause_accumulated_seconds
      - v_current_pause
    )::integer
  );

  IF p_distance_meters IS NOT NULL
     AND p_distance_meters>0
     AND v_duration>0 THEN
    v_pace := v_duration/(p_distance_meters/1000.0);
    v_speed := (p_distance_meters/1000.0)/(v_duration/3600.0);
  END IF;

  UPDATE public.health_activity_sessions
  SET
    status='completed',
    ended_at=v_now,
    paused_at=NULL,
    pause_accumulated_seconds=pause_accumulated_seconds+v_current_pause,
    active_duration_seconds=v_duration,
    distance_meters=p_distance_meters,
    calories_kcal=p_calories_kcal,
    avg_hr_bpm=p_avg_hr_bpm,
    max_hr_bpm=p_max_hr_bpm,
    rpe=p_rpe,
    cadence_spm=p_cadence_spm,
    elevation_gain_m=p_elevation_gain_m,
    steps=p_steps,
    avg_pace_seconds_per_km=v_pace,
    avg_speed_kmh=v_speed,
    notes=NULLIF(btrim(p_notes),'')
  WHERE id=p_activity_id
    AND athlete_id=v_activity.athlete_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_activity.athlete_id,
    p_activity_id,
    'activity_completed',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'duration_seconds',v_duration,
      'distance_meters',p_distance_meters,
      'avg_pace_seconds_per_km',v_pace,
      'avg_speed_kmh',v_speed,
      'rpe',p_rpe
    ),
    auth.uid()
  );

  RETURN p_activity_id;
END;
$$;

-- 10) MANUAL COMPLETED ACTIVITY

CREATE OR REPLACE FUNCTION public.health_f20_create_manual_activity(
  p_athlete_id uuid,
  p_modality_code text,
  p_title text,
  p_started_at timestamptz,
  p_duration_seconds integer,
  p_client_event_id uuid,
  p_distance_meters numeric DEFAULT NULL,
  p_calories_kcal numeric DEFAULT NULL,
  p_avg_hr_bpm integer DEFAULT NULL,
  p_max_hr_bpm integer DEFAULT NULL,
  p_rpe numeric DEFAULT NULL,
  p_cadence_spm numeric DEFAULT NULL,
  p_elevation_gain_m numeric DEFAULT NULL,
  p_steps integer DEFAULT NULL,
  p_notes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_id uuid;
  v_title text;
  v_pace numeric := NULL;
  v_speed numeric := NULL;
  v_ended_at timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  IF NOT public.health_can_write_athlete(p_athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF p_duration_seconds IS NULL OR p_duration_seconds<=0 THEN
    RAISE EXCEPTION 'duration must be greater than zero';
  END IF;

  IF p_started_at IS NULL THEN
    RAISE EXCEPTION 'started_at is required';
  END IF;

  SELECT s.id
  INTO v_id
  FROM public.health_activity_sessions s
  WHERE s.athlete_id=p_athlete_id
    AND s.client_event_id=p_client_event_id
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  SELECT COALESCE(NULLIF(btrim(p_title),''),m.name)
  INTO v_title
  FROM public.health_activity_modalities m
  WHERE m.code=p_modality_code
    AND m.is_active=true;

  IF v_title IS NULL THEN
    RAISE EXCEPTION 'activity modality not found or inactive';
  END IF;

  v_ended_at := p_started_at+make_interval(secs=>p_duration_seconds);

  IF p_distance_meters IS NOT NULL
     AND p_distance_meters>0 THEN
    v_pace := p_duration_seconds/(p_distance_meters/1000.0);
    v_speed := (p_distance_meters/1000.0)/(p_duration_seconds/3600.0);
  END IF;

  INSERT INTO public.health_activity_sessions (
    athlete_id,
    modality_code,
    title,
    source,
    status,
    started_at,
    ended_at,
    active_duration_seconds,
    distance_meters,
    calories_kcal,
    avg_hr_bpm,
    max_hr_bpm,
    rpe,
    cadence_spm,
    elevation_gain_m,
    steps,
    avg_pace_seconds_per_km,
    avg_speed_kmh,
    notes,
    client_event_id,
    created_by_auth_user_id
  )
  VALUES (
    p_athlete_id,
    p_modality_code,
    v_title,
    'manual',
    'completed',
    p_started_at,
    v_ended_at,
    p_duration_seconds,
    p_distance_meters,
    p_calories_kcal,
    p_avg_hr_bpm,
    p_max_hr_bpm,
    p_rpe,
    p_cadence_spm,
    p_elevation_gain_m,
    p_steps,
    v_pace,
    v_speed,
    NULLIF(btrim(p_notes),''),
    p_client_event_id,
    auth.uid()
  )
  RETURNING id INTO v_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    p_athlete_id,
    v_id,
    'activity_completed',
    'user',
    gen_random_uuid(),
    v_ended_at,
    jsonb_build_object(
      'manual',true,
      'duration_seconds',p_duration_seconds,
      'distance_meters',p_distance_meters,
      'avg_pace_seconds_per_km',v_pace,
      'avg_speed_kmh',v_speed
    ),
    auth.uid()
  );

  RETURN v_id;
END;
$$;

-- 11) ADD SEGMENT / LAP

CREATE OR REPLACE FUNCTION public.health_f20_add_segment(
  p_activity_id uuid,
  p_client_event_id uuid,
  p_segment_type text DEFAULT 'lap',
  p_label text DEFAULT NULL,
  p_duration_seconds integer DEFAULT NULL,
  p_distance_meters numeric DEFAULT NULL,
  p_avg_hr_bpm integer DEFAULT NULL,
  p_cadence_spm numeric DEFAULT NULL,
  p_notes text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_activity public.health_activity_sessions%ROWTYPE;
  v_segment_id uuid;
  v_sequence integer;
  v_pace numeric := NULL;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT *
  INTO v_activity
  FROM public.health_activity_sessions
  WHERE id=p_activity_id;

  IF v_activity.id IS NULL THEN
    RAISE EXCEPTION 'activity not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_activity.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  SELECT s.id
  INTO v_segment_id
  FROM public.health_activity_segments s
  WHERE s.athlete_id=v_activity.athlete_id
    AND s.client_event_id=p_client_event_id
  LIMIT 1;

  IF v_segment_id IS NOT NULL THEN
    RETURN v_segment_id;
  END IF;

  SELECT coalesce(max(sequence_order),0)+1
  INTO v_sequence
  FROM public.health_activity_segments
  WHERE activity_session_id=p_activity_id
    AND athlete_id=v_activity.athlete_id;

  IF p_duration_seconds IS NOT NULL
     AND p_duration_seconds>0
     AND p_distance_meters IS NOT NULL
     AND p_distance_meters>0 THEN
    v_pace := p_duration_seconds/(p_distance_meters/1000.0);
  END IF;

  INSERT INTO public.health_activity_segments (
    activity_session_id,
    athlete_id,
    sequence_order,
    segment_type,
    label,
    duration_seconds,
    distance_meters,
    pace_seconds_per_km,
    avg_hr_bpm,
    cadence_spm,
    notes,
    client_event_id
  )
  VALUES (
    p_activity_id,
    v_activity.athlete_id,
    v_sequence,
    p_segment_type,
    NULLIF(btrim(p_label),''),
    p_duration_seconds,
    p_distance_meters,
    v_pace,
    p_avg_hr_bpm,
    p_cadence_spm,
    NULLIF(btrim(p_notes),''),
    p_client_event_id
  )
  RETURNING id INTO v_segment_id;

  INSERT INTO public.health_activity_events (
    athlete_id,
    activity_session_id,
    activity_segment_id,
    event_type,
    source,
    client_event_id,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_activity.athlete_id,
    p_activity_id,
    v_segment_id,
    'segment_added',
    'user',
    gen_random_uuid(),
    jsonb_build_object(
      'sequence_order',v_sequence,
      'segment_type',p_segment_type,
      'duration_seconds',p_duration_seconds,
      'distance_meters',p_distance_meters,
      'pace_seconds_per_km',v_pace
    ),
    auth.uid()
  );

  RETURN v_segment_id;
END;
$$;

-- 12) FUNCTION PERMISSIONS

REVOKE ALL ON FUNCTION public.health_f20_guard_single_live_session()
FROM PUBLIC, anon, authenticated;

REVOKE ALL ON FUNCTION public.health_f20_start_activity(uuid,text,text,uuid)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f20_pause_activity(uuid,uuid)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f20_resume_activity(uuid,uuid)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f20_complete_activity(uuid,uuid,numeric,numeric,integer,integer,numeric,numeric,numeric,integer,text)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f20_create_manual_activity(uuid,text,text,timestamptz,integer,uuid,numeric,numeric,integer,integer,numeric,numeric,numeric,integer,text)
FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.health_f20_add_segment(uuid,uuid,text,text,integer,numeric,integer,numeric,text)
FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.health_f20_start_activity(uuid,text,text,uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f20_pause_activity(uuid,uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f20_resume_activity(uuid,uuid)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f20_complete_activity(uuid,uuid,numeric,numeric,integer,integer,numeric,numeric,numeric,integer,text)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f20_create_manual_activity(uuid,text,text,timestamptz,integer,uuid,numeric,numeric,integer,integer,numeric,numeric,numeric,integer,text)
TO authenticated;
GRANT EXECUTE ON FUNCTION public.health_f20_add_segment(uuid,uuid,text,text,integer,numeric,integer,numeric,text)
TO authenticated;

-- End F20 v1.
